    CONSTRAINT agent_policies_per_day_check CHECK (((per_day >= 1) AND (per_day <= 50))),
    CONSTRAINT agent_policies_reason_check CHECK (((char_length(btrim(reason)) >= 1) AND (char_length(btrim(reason)) <= 500)))
);

