    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    refused boolean DEFAULT false NOT NULL,
    error text,
    failure_kind text,
    CONSTRAINT eval_cells_error_check CHECK ((char_length(error) <= 500)),
    CONSTRAINT eval_cells_failure_kind_check CHECK ((failure_kind = ANY (ARRAY['throttled'::text, 'provider'::text, 'tool'::text, 'error'::text])))
);

CREATE TABLE public.eval_run_transitions (
    from_state public.eval_state NOT NULL,
    to_state public.eval_state NOT NULL
);

CREATE TABLE public.eval_runs (
    id uuid DEFAULT uuidv7() NOT NULL,
    kind public.eval_kind NOT NULL,
    state public.eval_state NOT NULL,
    area_id text,
    baseline_edition_seq bigint,
    tool_schema_digest text NOT NULL,
    model_id text NOT NULL,
    client_label text NOT NULL,
    test_set_digest bytea NOT NULL,
    tries smallint NOT NULL,
    flip_repeats smallint DEFAULT 7 NOT NULL,
    estimated_cost_micros bigint NOT NULL,
    actual_cost_micros bigint DEFAULT 0 NOT NULL,
    approved_by uuid,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    requested_by uuid,
    judge_model_id text,
    system_prompt_digest text,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    failure text,
    answer_family text NOT NULL,
    judge_family text NOT NULL,
    answer_vendor text NOT NULL,
    judge_vendor text NOT NULL,
    answer_provider text NOT NULL,
    judge_provider text NOT NULL,
    worker text,
    lease_until timestamp with time zone,
    cost_ceiling_micros bigint,
    CONSTRAINT eval_runs_cost_ceiling_micros_check CHECK ((cost_ceiling_micros >= 0)),
    CONSTRAINT eval_runs_failure_check CHECK ((char_length(failure) <= 500)),
    CONSTRAINT eval_runs_tries_check CHECK ((tries >= 1)),
    CONSTRAINT eval_runs_worker_check CHECK ((char_length(worker) <= 100))
);

CREATE TABLE public.eval_transcripts (
    cell_id uuid NOT NULL,
    messages jsonb NOT NULL,
    tool_calls jsonb DEFAULT '[]'::jsonb NOT NULL
);

CREATE TABLE public.feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    delivery_id uuid,
    verdict public.feedback_verdict NOT NULL,
    note text,
    client_label text NOT NULL,
    gap_id uuid,
    created_hour timestamp with time zone DEFAULT date_trunc('hour'::text, now(), 'UTC'::text) NOT NULL,
    area_id text,
    CONSTRAINT feedback_client_label_check CHECK ((client_label ~ '^[a-z0-9_.-]{1,40}$'::text)),
    CONSTRAINT feedback_created_hour_check CHECK ((created_hour = date_trunc('hour'::text, created_hour, 'UTC'::text))),
    CONSTRAINT feedback_id_check CHECK ((uuid_extract_version(id) = 4)),
    CONSTRAINT feedback_note_check CHECK ((char_length(note) <= 500))
);

CREATE TABLE public.gap_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    gap_id uuid NOT NULL,
    source text NOT NULL,
    note text NOT NULL,
    created_hour timestamp with time zone DEFAULT date_trunc('hour'::text, now(), 'UTC'::text) NOT NULL,
    delete_after timestamp with time zone DEFAULT (date_trunc('hour'::text, now(), 'UTC'::text) + '180 days'::interval) NOT NULL,
    CONSTRAINT gap_notes_created_hour_check CHECK ((created_hour = date_trunc('hour'::text, created_hour, 'UTC'::text))),
    CONSTRAINT gap_notes_delete_after_hour CHECK ((delete_after = date_trunc('hour'::text, delete_after, 'UTC'::text))),
    CONSTRAINT gap_notes_id_check CHECK ((uuid_extract_version(id) = 4)),
    CONSTRAINT gap_notes_note_check CHECK (((char_length(note) >= 1) AND (char_length(note) <= 500))),
    CONSTRAINT gap_notes_source_check CHECK ((source = ANY (ARRAY['report_gap'::text, 'feedback'::text, 'owner'::text, 'person'::text])))
);

CREATE TABLE public.gap_report_keys (
    retry_digest bytea NOT NULL,
    request_digest bytea NOT NULL,
    gap_id uuid NOT NULL,
    expires_hour timestamp with time zone DEFAULT (date_trunc('hour'::text, now(), 'UTC'::text) + '25:00:00'::interval) NOT NULL,
    CONSTRAINT gap_report_keys_expires_hour_check CHECK ((expires_hour = date_trunc('hour'::text, expires_hour, 'UTC'::text))),
    CONSTRAINT gap_report_keys_request_digest_check CHECK ((octet_length(request_digest) = 32)),
    CONSTRAINT gap_report_keys_retry_digest_check CHECK ((octet_length(retry_digest) = 32))
);

CREATE TABLE public.gap_transitions (
    from_status public.gap_status NOT NULL,
    to_status public.gap_status NOT NULL
);

CREATE TABLE public.gap_weekly_counts (
    gap_id uuid NOT NULL,
    week date NOT NULL,
    reports integer DEFAULT 0 NOT NULL,
    no_item_calls integer DEFAULT 0 NOT NULL,
    human_reports integer DEFAULT 0 NOT NULL,
    CONSTRAINT gap_weekly_counts_human_reports CHECK (((human_reports >= 0) AND (human_reports <= reports)))
);

CREATE TABLE public.gaps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ref text DEFAULT public.cl_short_id('gap'::text) NOT NULL,
    topic_id uuid NOT NULL,
    type public.gap_type NOT NULL,
    status public.gap_status DEFAULT 'open'::public.gap_status NOT NULL,
    severity smallint DEFAULT 2 NOT NULL,
    opened_by_case smallint NOT NULL,
    first_seen date DEFAULT ((now() AT TIME ZONE 'UTC'::text))::date NOT NULL,
    last_seen date DEFAULT ((now() AT TIME ZONE 'UTC'::text))::date NOT NULL,
    created_at timestamp with time zone DEFAULT date_trunc('hour'::text, now(), 'UTC'::text) NOT NULL,
    status_since timestamp with time zone DEFAULT date_trunc('hour'::text, now(), 'UTC'::text) NOT NULL,
    resolved_edition_seq bigint,
    CONSTRAINT gaps_created_hour CHECK ((created_at = date_trunc('hour'::text, created_at, 'UTC'::text))),
    CONSTRAINT gaps_id_check CHECK ((uuid_extract_version(id) = 4)),
    CONSTRAINT gaps_opened_by_case_check CHECK (((opened_by_case >= 1) AND (opened_by_case <= 5))),
    CONSTRAINT gaps_resolved_edition CHECK (((resolved_edition_seq IS NULL) OR (status = 'resolved'::public.gap_status))),
    CONSTRAINT gaps_severity_check CHECK (((severity >= 1) AND (severity <= 4))),
    CONSTRAINT gaps_status_since_hour CHECK ((status_since = date_trunc('hour'::text, status_since, 'UTC'::text)))
);

CREATE TABLE public.global_role_grants (
    person_id uuid NOT NULL,
