);

CREATE TABLE public.golden_questions (
    id text NOT NULL,
    area_id text NOT NULL,
    wordings jsonb NOT NULL,
    scope jsonb NOT NULL,
    expected jsonb NOT NULL,
    rubrics jsonb DEFAULT '[]'::jsonb NOT NULL,
    risk public.risk_level DEFAULT 'normal'::public.risk_level NOT NULL,
    source text NOT NULL,
    status public.question_status DEFAULT 'active'::public.question_status NOT NULL,
    split public.question_split NOT NULL,
    set_aside_reason text,
    revision integer DEFAULT 1 NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    as_of date,
    CONSTRAINT golden_questions_id_check CHECK ((id ~ '^[a-z0-9][a-z0-9-]{2,80}$'::text)),
    CONSTRAINT golden_questions_set_aside_reason_check CHECK ((char_length(set_aside_reason) <= 500)),
    CONSTRAINT golden_questions_wordings_check CHECK (((jsonb_typeof(wordings) = 'array'::text) AND (jsonb_array_length(wordings) >= 2)))
);

CREATE TABLE public.idempotency_keys (
    person_id uuid NOT NULL,
    key text NOT NULL,
    method text NOT NULL,
    path text NOT NULL,
    request_hash bytea NOT NULL,
    status integer,
    response jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval) NOT NULL,
    CONSTRAINT idempotency_keys_key_check CHECK (((char_length(key) >= 8) AND (char_length(key) <= 128)))
);

CREATE TABLE public.import_batches (
    id uuid DEFAULT uuidv7() NOT NULL,
    created_by uuid NOT NULL,
    mode text NOT NULL,
    source_name text,
