    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT import_batches_mode_check CHECK ((mode = ANY (ARRAY['dry_run'::text, 'apply'::text])))
);

CREATE TABLE public.inbox_items (
    id uuid DEFAULT uuidv7() NOT NULL,
    person_id uuid NOT NULL,
    event_seq bigint,
    kind text NOT NULL,
    area_id text,
    subject_type text NOT NULL,
    subject_id text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id uuid
);

CREATE TABLE public.item_bin (
    id uuid DEFAULT uuidv7() NOT NULL,
    item_id text NOT NULL,
    version_id uuid NOT NULL,
    area_id text NOT NULL,
    reason text NOT NULL,
    binned_by uuid NOT NULL,
    binned_at timestamp with time zone DEFAULT now() NOT NULL,
    binned_edition bigint,
    restored_by uuid,
    restored_at timestamp with time zone,
    restored_via text,
    restored_edition bigint,
    restored_area text,
    rescue_proposal uuid,
    CONSTRAINT item_bin_check CHECK ((((restored_at IS NULL) = (restored_by IS NULL)) AND ((restored_at IS NULL) = (restored_via IS NULL)))),
    CONSTRAINT item_bin_check1 CHECK (((restored_edition IS NULL) OR (restored_at IS NOT NULL))),
    CONSTRAINT item_bin_reason_check CHECK (((char_length(btrim(reason)) >= 1) AND (char_length(btrim(reason)) <= 500))),
    CONSTRAINT item_bin_rescue CHECK (((COALESCE((restored_via = 'rescue'::text), false) = (restored_area IS NOT NULL)) AND ((restored_area IS NULL) = (rescue_proposal IS NULL)) AND ((restored_area IS NULL) OR (restored_edition IS NULL)))),
    CONSTRAINT item_bin_restored_via_check CHECK ((restored_via = ANY (ARRAY['restore'::text, 'rollback'::text, 'rescue'::text])))
);

CREATE TABLE public.item_changes (
    id uuid DEFAULT uuidv7() NOT NULL,
    action text NOT NULL,
    made_by uuid NOT NULL,
    made_at timestamp with time zone DEFAULT now() NOT NULL,
    summary text NOT NULL,
    items jsonb NOT NULL,
    undo jsonb DEFAULT '{}'::jsonb NOT NULL,
    undone_at timestamp with time zone,
    CONSTRAINT item_changes_action_check CHECK ((action = ANY (ARRAY['archived'::text, 'deleted'::text, 'moved'::text, 'kind'::text, 'owners'::text, 'checked'::text]))),
    CONSTRAINT item_changes_items_check CHECK (((jsonb_typeof(items) = 'array'::text) AND (jsonb_array_length(items) > 0))),
    CONSTRAINT item_changes_summary_check CHECK (((char_length(btrim(summary)) >= 1) AND (char_length(btrim(summary)) <= 500)))
);

CREATE TABLE public.item_owners (
    item_id text NOT NULL,
    person_id uuid NOT NULL,
    added_by uuid NOT NULL,
    added_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.item_reads (
    person_id uuid NOT NULL,
    item_id text NOT NULL,
    read_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.item_version_conflicts (
    version_id uuid NOT NULL,
    other_item_id text NOT NULL,
    authority_url text,
    authority_quote text
);

CREATE TABLE public.item_version_dimension_values (
    version_id uuid NOT NULL,
    dimension_key text NOT NULL,
    value_key text NOT NULL
);

CREATE TABLE public.item_version_dimensions (
    version_id uuid NOT NULL,
    dimension_key text NOT NULL
);

CREATE TABLE public.item_version_evidence (
    version_id uuid NOT NULL,
    "position" smallint NOT NULL,
    url text NOT NULL,
    quote text NOT NULL,
    read_on date NOT NULL,
    source_change_mark text,
    CONSTRAINT item_version_evidence_position_check CHECK (("position" >= 0)),
    CONSTRAINT item_version_evidence_quote_check CHECK (((char_length(quote) >= 1) AND (char_length(quote) <= 500))),
    CONSTRAINT item_version_evidence_url_check CHECK (((url ~ '^https?://'::text) AND (char_length(url) <= 2000)))
);

CREATE TABLE public.item_version_mentions (
    version_id uuid NOT NULL,
    field public.mention_field NOT NULL,
    "position" smallint NOT NULL,
    term_key text,
    item_id text,
    area_id text,
    label text NOT NULL,
    definition_ref text,
    change_mark text,
    term_id uuid,
    CONSTRAINT item_version_mentions_check CHECK ((num_nonnulls(term_key, item_id, area_id, term_id) = 1)),
    CONSTRAINT item_version_mentions_label_check CHECK (((char_length(label) >= 1) AND (char_length(label) <= 120))),
    CONSTRAINT item_version_mentions_mark CHECK (((definition_ref IS NULL) = (change_mark IS NULL))),
    CONSTRAINT item_version_mentions_position_check CHECK (("position" >= 0)),
    CONSTRAINT item_version_mentions_term_key_check CHECK ((term_key ~ '^(metric|dim|val):'::text))
);

CREATE TABLE public.item_version_metrics (
    version_id uuid NOT NULL,
    metric_key text NOT NULL
);

CREATE TABLE public.item_version_refs (
    version_id uuid NOT NULL,
    definition_ref text NOT NULL,
    change_mark text NOT NULL
);

CREATE TABLE public.item_version_replaces (
    version_id uuid NOT NULL,
    replaced_item_id text NOT NULL
);

CREATE TABLE public.item_version_service (
    item_id text NOT NULL,
    version_id uuid NOT NULL,
    editions int8range NOT NULL,
    CONSTRAINT item_version_service_editions_check CHECK (((NOT isempty(editions)) AND lower_inc(editions) AND (NOT lower_inf(editions))))
);

CREATE TABLE public.item_versions (
    id uuid DEFAULT uuidv7() NOT NULL,
    item_id text NOT NULL,
    version_no integer NOT NULL,
    supersedes_version_id uuid,
    area_id text NOT NULL,
    title text NOT NULL,
    summary text NOT NULL,
    body text,
    risk public.risk_level NOT NULL,
    claim public.claim_level DEFAULT 'fact_only'::public.claim_level NOT NULL,
    claim_authority text,
    claim_quote text,
    audience_groups text[],
    owner_id uuid,
    proposer_id uuid,
    edited_by uuid,
    created_via public.creation_channel NOT NULL,
    valid_from date NOT NULL,
    valid_until date,
    validity daterange GENERATED ALWAYS AS (daterange(valid_from, valid_until, '[)'::text)) STORED,
    review_date date,
    not_to_conclude text DEFAULT 'cause not proven'::text NOT NULL,
    is_recheck boolean DEFAULT false NOT NULL,
    content_digest bytea NOT NULL,
    core_digest bytea NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    search tsvector GENERATED ALWAYS AS (((setweight(to_tsvector('simple'::regconfig, title), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, summary), 'B'::"char")) || setweight(to_tsvector('simple'::regconfig, COALESCE(body, ''::text)), 'C'::"char"))) STORED,
    summary_markup text,
    body_markup text,
    created_xact xid8 DEFAULT pg_current_xact_id() NOT NULL,
    kind public.item_kind NOT NULL,
    CONSTRAINT item_versions_audience_groups_check CHECK (((audience_groups IS NULL) OR (cardinality(audience_groups) > 0))),
    CONSTRAINT item_versions_body_check CHECK (((body IS NULL) OR (char_length(body) <= 20000))),
    CONSTRAINT item_versions_body_markup_plain CHECK (((body_markup IS NULL) OR ((body IS NOT NULL) AND (public.cl_strip_mentions(body_markup) = body)))),
    CONSTRAINT item_versions_check CHECK (((valid_until IS NULL) OR (valid_until > valid_from))),
    CONSTRAINT item_versions_check1 CHECK (((valid_until IS NOT NULL) OR (review_date IS NOT NULL))),
    CONSTRAINT item_versions_check2 CHECK (((claim = 'effect_stated'::public.claim_level) = ((claim_authority IS NOT NULL) AND (claim_quote IS NOT NULL)))),
    CONSTRAINT item_versions_claim_authority_check CHECK (((claim_authority IS NULL) OR (char_length(claim_authority) <= 200))),
    CONSTRAINT item_versions_claim_quote_check CHECK (((claim_quote IS NULL) OR (char_length(claim_quote) <= 500))),
    CONSTRAINT item_versions_content_digest_check CHECK ((length(content_digest) = 32)),
    CONSTRAINT item_versions_core_digest_check CHECK ((length(core_digest) = 32)),
    CONSTRAINT item_versions_source_check CHECK (((created_via = 'source'::public.creation_channel) = (proposer_id IS NULL))),
    CONSTRAINT item_versions_summary_check CHECK ((char_length(summary) <= 280)),
    CONSTRAINT item_versions_summary_markup_plain CHECK (((summary_markup IS NULL) OR (public.cl_strip_mentions(summary_markup) = summary))),
    CONSTRAINT item_versions_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 200))),
    CONSTRAINT item_versions_version_no_check CHECK ((version_no >= 1))
);

CREATE TABLE public.items (
    id text DEFAULT public.cl_short_id('itm'::text) NOT NULL,
